package kr.yunseok.touchmacro;

import android.accessibilityservice.AccessibilityService;
import android.app.AlertDialog;
import android.graphics.Rect;
import android.os.SystemClock;
import android.view.*;
import android.widget.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.json.JSONObject;
import org.junit.*;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;

/** 정상 부재의 복구와 실제 입력, 취소·기한·새 시작 경계를 확인합니다. */
@RunWith(AndroidJUnit4.class) public class MissingRetryFlowTest {
    final GuidedFlowTest h=new GuidedFlowTest();final AtomicInteger reads=new AtomicInteger(),taps=new AtomicInteger(),recoveries=new AtomicInteger();
    final CountDownLatch held=new CountDownLatch(1),release=new CountDownLatch(1);Field source;MacroService.ScreenSource original;AlertDialog dialog;
    @Before public void boot()throws Exception{h.boot();h.fixture();h.main(()->h.entry.setOnClickListener(v->taps.incrementAndGet()));source=MacroService.class.getDeclaredField("accessibilitySource");source.setAccessible(true);original=(MacroService.ScreenSource)source.get(h.svc);}
    @After public void end()throws Exception{release.countDown();h.end();source.set(h.svc,original);h.main(()->{if(dialog!=null)dialog.dismiss();});}
    Step word(String policy,boolean infinite)throws Exception{JSONObject json=new Step("TEXT_TAP").json().put("text","안내 대상").put("source","ACCESS").put("match","EXACT").put("immediate",true).put("timeout",0).put("after",0).put("retries",0).put("retryDelay",300).put("failure",policy).put("retryForever",infinite);return new Step(json);}
    Macro macro(Step word){Macro m=new Macro();m.startDelay=0;m.maxMinutes=0;m.steps.add(word);return m;}
    void start(Macro m){h.main(()->h.svc.start(m));}
    void normalAfter(int absent)throws Exception{source.set(h.svc,(MacroService.ScreenSource)token->reads.incrementAndGet()<=absent?new ArrayList<>():original.read(token));}
    @Test public void infiniteRetryPastFiniteZeroThenTouchesExactlyOnce()throws Exception{normalAfter(5);start(macro(word("RETRY",true)));h.waitFor(()->!h.svc.running,6000,"계속 재시도가 첫 부재에서 종료됐습니다");assertTrue(reads.get()>=6);assertEquals(1,taps.get());assertEquals(1,h.svc.hudProgress().completed);}
    @Test public void finiteZeroStopsAfterOneNormalAbsence()throws Exception{normalAfter(100);start(macro(word("RETRY",false)));h.waitFor(()->!h.svc.running,3000,"유한0 재시도가 종료되지 않았습니다");assertEquals(1,reads.get());assertEquals(0,taps.get());assertEquals(0,h.svc.hudProgress().completed);assertTrue(h.svc.status.contains("글자를 찾지 못했습니다"));}
    @Test public void finiteTwoRetriesReadExactlyThreeTimes()throws Exception{normalAfter(100);Step s=word("RETRY",false);s.retries=2;start(macro(s));h.waitFor(()->!h.svc.running,4000,"유한 재시도 종료 없음");assertEquals(3,reads.get());assertEquals(0,taps.get());assertEquals(0,h.svc.hudProgress().completed);}
    void backDialog(){h.main(()->{Button target=new Button(h.a);target.setText("안내 대상");target.setOnClickListener(v->taps.incrementAndGet());dialog=new AlertDialog.Builder(h.a).setTitle("재시도 대상").setView(target).create();dialog.setOnKeyListener((d,key,event)->{if(key!=KeyEvent.KEYCODE_BACK)return false;if(event.getAction()==KeyEvent.ACTION_UP)recoveries.incrementAndGet();return true;});dialog.show();});h.in.waitForIdleSync();}
    @Test public void normalAbsenceRepeatsRealBackBeforeOneSuccessfulTap()throws Exception{backDialog();source.set(h.svc,(MacroService.ScreenSource)token->recoveries.get()<3?new ArrayList<>():original.read(token));start(macro(word("BACK_RETRY",true)));h.waitFor(()->!h.svc.running,6000,"뒤로가기 재시도 완료 없음");assertEquals(3,recoveries.get());assertEquals(1,taps.get());assertEquals(1,h.svc.hudProgress().completed);}
    void swipeRetry(String policy,double expectedFrom,double expectedTo)throws Exception{
        AtomicReference<Float> from=new AtomicReference<>(0f),to=new AtomicReference<>(0f),swipeFrom=new AtomicReference<>(0f);AtomicBoolean moved=new AtomicBoolean();h.main(()->{Button target=new Button(h.a);target.setText("안내 대상");target.setOnClickListener(v->taps.incrementAndGet());target.setOnTouchListener((v,event)->{if(event.getActionMasked()==MotionEvent.ACTION_DOWN){from.set(event.getRawY());moved.set(false);}if(event.getActionMasked()==MotionEvent.ACTION_MOVE&&Math.abs(event.getRawY()-from.get())>ViewConfiguration.get(h.a).getScaledTouchSlop())moved.set(true);if(event.getActionMasked()==MotionEvent.ACTION_UP){if(moved.get()){swipeFrom.set(from.get());to.set(event.getRawY());recoveries.incrementAndGet();}else v.performClick();}return true;});h.a.setContentView(target);});h.in.waitForIdleSync();
        source.set(h.svc,(MacroService.ScreenSource)token->recoveries.get()<2?new ArrayList<>():original.read(token));start(macro(word(policy,true)));h.waitFor(()->!h.svc.running,6000,"실제 스와이프 재시도 완료 없음");assertEquals(2,recoveries.get());assertEquals(1,taps.get());assertEquals(h.svc.size()[1]*expectedFrom,swipeFrom.get(),3);assertEquals(h.svc.size()[1]*expectedTo,to.get(),3);assertEquals(1,h.svc.hudProgress().completed);
        assertTrue("스와이프 방향이 반대입니다",expectedTo>expectedFrom?to.get()>h.svc.size()[1]*expectedFrom:to.get()<h.svc.size()[1]*expectedFrom);
    }
    @Test public void pullDownRefreshRetriesOnlyAfterNormalAbsence()throws Exception{swipeRetry("PULL_RETRY",.28,.72);}
    @Test public void upwardScrollRetryRetainsShortDistance()throws Exception{swipeRetry("SCROLL_RETRY",.75,.525);}
    @Test public void selectedActionRespectsRepeatAndAfterWithoutCompletingMacroRound()throws Exception{
        AtomicLong first=new AtomicLong(),last=new AtomicLong(),finalTap=new AtomicLong();Rect[] box={null};h.main(()->{LinearLayout body=new LinearLayout(h.a);body.setPadding(40,Ui.dp(h.a,180),40,0);body.setOrientation(LinearLayout.VERTICAL);Button recover=new Button(h.a);recover.setText("복구 동작");recover.setOnClickListener(v->{assertEquals(0,h.svc.hudProgress().completed);long now=SystemClock.elapsedRealtime();first.compareAndSet(0,now);last.set(now);recoveries.incrementAndGet();});body.addView(recover,new LinearLayout.LayoutParams(-1,Ui.dp(h.a,70)));body.addView(h.entry=new Button(h.a),new LinearLayout.LayoutParams(-1,Ui.dp(h.a,70)));h.entry.setText("안내 대상");h.entry.setOnClickListener(v->{taps.incrementAndGet();finalTap.set(SystemClock.elapsedRealtime());});h.a.setContentView(body);});h.in.waitForIdleSync();h.main(()->box[0]=h.bounds(((LinearLayout)h.entry.getParent()).getChildAt(0)));
        Step recovery=new Step("TAP");recovery.x=box[0].exactCenterX()*100.0/h.svc.size()[0];recovery.y=box[0].exactCenterY()*100.0/h.svc.size()[1];recovery.duration=40;recovery.repeat=2;recovery.after=250;
        Step text=new Step(word("ACTION_RETRY",true).json().put("recoveryTarget",1));Macro m=new Macro();m.startAt=2;m.startDelay=0;m.maxMinutes=0;m.steps.add(recovery);m.steps.add(text);source.set(h.svc,(MacroService.ScreenSource)token->recoveries.get()<2?new ArrayList<>():original.read(token));start(m);h.waitFor(()->!h.svc.running,6000,"지정 동작 복구 완료 없음");assertEquals(2,recoveries.get());assertEquals(1,taps.get());assertTrue(last.get()-first.get()>=250);assertTrue(finalTap.get()-last.get()>=550);assertEquals(1,h.svc.hudProgress().completed);
    }
    @Test public void pauseFreezesRetryAndResumeUsesFreshWord()throws Exception{normalAfter(1000);start(macro(word("RETRY",true)));h.waitFor(()->reads.get()>=2,3000,"재시도 시작 없음");h.main(()->h.svc.togglePause());SystemClock.sleep(150);int frozen=reads.get();SystemClock.sleep(500);assertEquals(frozen,reads.get());assertEquals(0,taps.get());source.set(h.svc,original);h.main(()->h.svc.togglePause());h.waitFor(()->!h.svc.running,3000,"계속 실행 뒤 새 화면 확인 없음");assertEquals(1,taps.get());}
    @Test public void stopDuringHeldReadNeverRunsRecoveryOrTouchesLateResult()throws Exception{source.set(h.svc,(MacroService.ScreenSource)token->{held.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}return new ArrayList<>();});start(macro(word("BACK_RETRY",true)));assertTrue(held.await(3,TimeUnit.SECONDS));long at=SystemClock.elapsedRealtime();h.main(()->h.svc.stop());assertFalse(h.svc.running);assertTrue(SystemClock.elapsedRealtime()-at<1000);release.countDown();SystemClock.sleep(400);assertEquals(0,taps.get());assertEquals(0,h.svc.hudProgress().completed);}
    @Test public void newStartPreventsOldHeldAbsenceFromRunningSelectedAction()throws Exception{AtomicInteger call=new AtomicInteger();source.set(h.svc,(MacroService.ScreenSource)token->{if(call.incrementAndGet()==1){held.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}return new ArrayList<>();}return original.read(token);});Rect[] box={null};h.main(()->box[0]=h.bounds(h.entry));Step recovery=new Step("TAP");recovery.x=box[0].exactCenterX()*100.0/h.svc.size()[0];recovery.y=box[0].exactCenterY()*100.0/h.svc.size()[1];Macro old=new Macro();old.startDelay=0;old.startAt=2;old.steps.add(recovery);old.steps.add(new Step(word("ACTION_RETRY",true).json().put("recoveryTarget",1)));start(old);assertTrue(held.await(3,TimeUnit.SECONDS));start(macro(word("STOP",false)));release.countDown();h.waitFor(()->!h.svc.running,4000,"새 실행 완료 없음");assertEquals(1,taps.get());assertEquals(1,h.svc.hudProgress().completed);}
    @Test public void capturePermissionErrorNeverBecomesMissingBack()throws Exception{backDialog();Field capture=MacroService.class.getDeclaredField("screenshotSource");capture.setAccessible(true);Object before=capture.get(h.svc);capture.set(h.svc,(MacroService.ScreenshotSource)(executor,callback)->callback.onFailure(AccessibilityService.ERROR_TAKE_SCREENSHOT_NO_ACCESSIBILITY_ACCESS));try{Step s=word("BACK_RETRY",true);s.source="OCR";start(macro(s));h.waitFor(()->!h.svc.running,4000,"캡처 권한 오류가 숨겨졌습니다");assertEquals(0,recoveries.get());assertEquals(0,taps.get());assertFalse(h.svc.status.contains("글자를 찾지 못했습니다"));}finally{capture.set(h.svc,before);}}
    @Test public void explicitOverallDeadlineStillStopsInfiniteRetry()throws Exception{normalAfter(1000);start(macro(word("RETRY",true)));h.waitFor(()->reads.get()>=1,2000,"재시도 시작 없음");Field deadline=MacroService.class.getDeclaredField("deadline");deadline.setAccessible(true);deadline.setLong(h.svc,SystemClock.elapsedRealtime()+500);h.waitFor(()->!h.svc.running,2000,"명시 전체 기한을 무시했습니다");assertTrue(h.svc.status.contains("최대 실행 시간"));assertEquals(0,taps.get());assertEquals(0,h.svc.hudProgress().completed);}
}
